  if (!j.acoes.some(a => a.onde === e.onde)) j.acoes.push({ prioridade: 'MÉDIA', onde: e.onde, o_que: `Trocar o dia da semana: ${e.certo}.`, agente: 'Físico' }); });
const md = rvCab('MD 24', 'AUDITORIA FÍSICA (AGENTE 2, O FÍSICO)', 'AUDITORIA GERADA PELO FLUXO', 'MD 22, regras do mundo, Capítulos', 'Revisão de continuidade')
  + `> Lei aplicada: ${j.lei}\n\n## PARTE A — USOS DAS REGRAS (vereditos)\n\n${rvTabela(['#', 'Onde', 'O quê', 'Parâmetros', 'Veredito', 'Nota'], j.eventos.map(e => [e.id, e.onde, e.o_que, e.parametros, e.veredito === 'FURO' ? '**FURO**' : e.veredito, e.nota]))}\n`
  + `## PARTE B — TIMELINE\n\n${j.timeline.resumo}\n${cal.conferido ? `\nCalendário de ${cal.ano} conferido pelo código: ${cal.datas} datas com dia da semana.\n` : ''}\n${rvTabela(['Onde', 'Erro', 'Correção'], j.timeline.erros.map(e => [e.onde, e.erro, e.correcao]))}\n`
  + `## PARTE C — MATRIZ DE CONHECIMENTO\n\n${rvTabela(['Personagem', 'Sabe', 'Desde', 'Fonte em cena', 'Risco'], j.matriz.map(m => [m.personagem, m.sabe, m.desde, m.fonte_em_cena ? 'sim' : 'NÃO', m.risco]))}\n`
  + `## FUROS CLASSIFICADOS\n\n${rvTabela(['Gravidade', 'Onde', 'Furo', 'Correção'], j.furos.map(f => [f.gravidade, f.onde, f.furo, f.correcao]))}` + rvAcoesMd(j.acoes);
return [{ json: { rel: JSON.stringify({ agente: 'fisico', ok: !!x.lei || j.eventos.length > 0, json: j, md, acoes: j.acoes }) } }];

} catch (erro) {
  return [{ json: { rel: JSON.stringify({ agente: 'fisico', ok: false, erro: String(erro.message || erro), json: {}, acoes: [], md: '# MD 24 — AUDITORIA\n\n⚠️ O relatório não saiu: ' + String(erro.message || erro) }) } }];
}
